// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: positive deposit, wide enough, excluding the degenerate
        // value where the mutant's depositsCount (1 wei) happens to equal the deposit.
        amount = bound(amount, 2, 1e18);

        // Fund the owner (address(this), the deployer of c) and deposit via fallback.
        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(ok);

        uint256 depositsBefore = c.depositsCount();

        // Owner drains everything.
        vm.prank(address(this));
        c.withdrawAll();

        // General rule: after an owner withdrawAll, the reference empties the
        // contract's balance completely. The mutant transfers only
        // depositsCount (= 1 wei) while balance is amount >= 2 wei, leaving
        // a positive balance (and the deposit counter must stay intact).
        assertTrue(address(c).balance == 0 && c.depositsCount() == depositsBefore);
    }

    // Allow this contract to receive the withdrawn Ether (owner of c).
    receive() external payable {}
}
